input.sparql:
SELECT ?sensor ?type ?point WHERE {
  ?sensor rdf:type ?type .
  FILTER(?type IN (brick:Electric_Power_Sensor, brick:Electric_Energy_Sensor))
  OPTIONAL { ?sensor brick:isPointOf ?point . }
}

SELECT ?sensor ?type WHERE {
  ?sensor rdf:type ?type .
  FILTER(contains(str(?sensor), "Building") || contains(str(?sensor), "Main") || contains(str(?sensor), "Total"))
}

SELECT ?sensor ?type WHERE {
  ?sensor rdf:type ?type .
  ?type rdfs:subClassOf* brick:Sensor .
  FILTER(contains(str(?sensor), "Building") || contains(str(?sensor), "Main") || contains(str(?sensor), "Total"))
}

SELECT ?sensor WHERE {
  ?sensor rdf:type brick:Electric_Power_Sensor .
  ?sensor brick:isPointOf ?zone .
  ?zone rdf:type brick:Zone .
}

SELECT ?sensor ?point WHERE {
  ?sensor rdf:type brick:Electric_Power_Sensor .
  ?sensor brick:isPointOf ?point .
  FILTER(contains(str(?point), "Zone"))
}
